css:
.text {
  max-width: 50ch;
  padding: 16px;
  font-family: system-ui, sans-serif;
  font-size: 1.125rem;
  line-height: 1.6;
}

.text strong {
  font-weight: 600;
}

.text code {
  padding: 2px 5px;
  border-radius: 4px;
  background: #fed7aa;
  font-family: ui-monospace, monospace;
  font-size: 0.875em;
}

.text small {
  color: #71717a;
}
